 sealed class State(string id,string role,Guid? workspace=null,string? mode=null):AuthenticationStateProvider{public override Task<AuthenticationState> GetAuthenticationStateAsync(){var claims=new List<Claim>{new(ClaimTypes.NameIdentifier,id),new(ClaimTypes.Name,id),new(ClaimTypes.Role,role)};if(mode is not null)claims.Add(new(ProfileModes.Claim,mode));if(workspace is Guid selected)claims.Add(new(WorkspaceContext.Claim,selected.ToString()));return Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity(claims,"Test"))));}}
 sealed class Factory(DbContextOptions<AtsDbContext> options):IDbContextFactory<AtsDbContext>{public AtsDbContext CreateDbContext()=>new(options);}
 sealed class Mail:IAccountEmail{public bool Configured=>false;public Task Send(string address,string subject,string body)=>throw new InvalidOperationException("No Test Emails");}
 sealed class Fixture:IAsyncDisposable {
  readonly SqliteConnection connection=new("Data Source=:memory:");public Factory Factory=null!;readonly EphemeralDataProtectionProvider protection=new();
  public async Task Init(){await connection.OpenAsync();Factory=new(new DbContextOptionsBuilder<AtsDbContext>().UseSqlite(connection).Options);await using var db=Factory.CreateDbContext();await DatabaseInitializer.InitializeAsync(db);foreach(var role in new[]{"Employer","Recruiter","Candidate","Admin"})db.Roles.Add(new IdentityRole(role){Id=role});foreach(var id in new[]{"free","first","second","employee","admin"}){var role=id is "first" or "second"?"Employer":id=="admin"?"Admin":"Recruiter";db.Users.Add(new(){Id=id,FullName=id,UserName=id,Email=id+"@example.test",NormalizedEmail=(id+"@example.test").ToUpperInvariant(),EmailConfirmed=true,AccountType=id=="free"?AccountTypes.Freelance:id=="employee"?AccountTypes.Employee:role});db.UserRoles.Add(new(){UserId=id,RoleId=role});}await db.SaveChangesAsync();db.AdminPaymentDetails.Add(new AdminPaymentDetails{Id=AdminPaymentDetailsService.SettingsId,BankName="Test Bank",AccountTitle="Osynix Group",AccountNumber="1234567890"});await db.SaveChangesAsync();}
  public State Auth(string id,Guid? workspace=null,string? mode=null)=>new(id,id is "first" or "second"?"Employer":id=="admin"?"Admin":"Recruiter",workspace,mode);
  public Access Access(string id,Guid? workspace=null)=>new(Auth(id,workspace),Factory);
  public EmployerService Owner(string id)=>new(Auth(id),Access(id),Factory);
