  public async Task<Guid> Join(string owner,string id){var link=await Team(owner).Invite(id,id+"@example.test");var token=QueryHelpers.ParseQuery(new Uri(link.Link).Query)["token"].ToString();return await Team(owner).Accept(token,(await Auth(id).GetAuthenticationStateAsync()).User);}
  public ValueTask DisposeAsync()=>connection.DisposeAsync();
 }
