 await using(var db=f.Factory.CreateDbContext()){foreach(var spec in new[]{("Own",own.Id,"free","Active"),("Open",team,"free","Active"),("Closed",team,"free","Closed"),("Other",team,"employee","Active")}){var p=new Position{Reference=spec.Item1,WorkspaceId=spec.Item2,AssignedRecruiter=spec.Item3,Status=spec.Item4};var c=new Candidate{Name=spec.Item1,WorkspaceId=spec.Item2};db.AddRange(p,c,new Assessment{PositionId=p.Id,CandidateId=c.Id,State="Saved"});}await db.SaveChangesAsync();var m=await db.WorkspaceMemberships.SingleAsync(m=>m.WorkspaceId==team&&m.UserId=="free");m.CanViewTalentPool=true;await db.SaveChangesAsync();closedId=(await db.Candidates.SingleAsync(c=>c.Name=="Closed")).Id;otherId=(await db.Candidates.SingleAsync(c=>c.Name=="Other")).Id;openId=(await db.Candidates.SingleAsync(c=>c.Name=="Open")).Id;}
 Assert.Equal(new[]{"Closed","Open","Own"},(await f.Ats("free").TalentCandidates()).Select(c=>c.Name).Order().ToArray());Assert.Equal("Open",Assert.Single(await f.Ats("free",team).TalentCandidates()).Name);await f.Access("free").RequireTalentCandidate(closedId);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Access("free",team).RequireTalentCandidate(closedId));await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Access("free").RequireTalentCandidate(otherId));
 await using(var db=f.Factory.CreateDbContext()){(await db.WorkspaceMemberships.SingleAsync(m=>m.WorkspaceId==team&&m.UserId=="free")).Status="Inactive";await db.SaveChangesAsync();}Assert.Equal("Own",Assert.Single(await f.Ats("free").TalentCandidates()).Name);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Access("free").RequireTalentCandidate(openId));
 }
 [Fact]public async Task InvitationInboxContainsOnlyTheVerifiedRecipientsPendingRequests(){await using var f=new Fixture();await f.Init();await f.Team("first").Invite("Free","free@example.test");await f.Team("second").Invite("Employee","employee@example.test");var own=await f.Work("free").Notifications();Assert.Single(own.Invitations);Assert.Contains("TeamInvitation?token=",own.Invitations[0].Link);Assert.Empty((await f.Work("first").Notifications()).Invitations);await using(var db=f.Factory.CreateDbContext()){(await db.Users.FindAsync("free"))!.EmailConfirmed=false;await db.SaveChangesAsync();}await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Work("free").Notifications());}
 [Fact]public async Task PersonalSlotUsageIsSeparateFromEmployerAssignedPositions(){await using var f=new Fixture();await f.Init();var own=(await f.Owner("free").Overview()).Workspace;var team=await f.Join("first","free");await using(var db=f.Factory.CreateDbContext()){db.Positions.Add(new(){Reference="PERSONAL",WorkspaceId=own.Id,Title="Personal",AssignedRecruiter="free"});for(int i=0;i<3;i++)db.Positions.Add(new(){Reference="EMP"+i,WorkspaceId=team,Title="Employer Assignment",AssignedRecruiter="free"});db.Positions.Add(new(){Reference="NOT-MINE",WorkspaceId=team,Title="Other Team Member Position",AssignedRecruiter="employee",Status="Draft"});await db.SaveChangesAsync();}var summary=await f.Work("free").Overview();Assert.Equal(1,summary.PersonalSlotsUsed);Assert.Equal(1,summary.PersonalSlotsLimit);Assert.Equal(3,summary.Positions.Count(p=>!p.Personal));Assert.DoesNotContain(summary.Positions,p=>p.Reference=="NOT-MINE");Assert.Equal(1,(await f.Ats("free").Allowance())!.Used);}
 [Fact]public async Task FreelancerOwnsOneFreePositionSlotAndCannotCreateATeam(){await using var f=new Fixture();await f.Init();var overview=await f.Owner("free").Overview();Assert.Equal(AccountTypes.Freelance,overview.Workspace.Kind);Assert.Equal(1,overview.Workspace.FreePositionSlots);Assert.Equal(0,overview.Workspace.FreeRecruiterSeats);Assert.True(await f.Access("free").Can("Positions.Create"));Assert.True(await f.Access("free").Can("Clients.Create"));Assert.True(await f.Access("free").Can("Talent.View"));Assert.False(await f.Access("free").Can("Talent.Master"));await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Team("free").Invite("Employee","employee@example.test"));var clients=new WorkspaceService(f.Factory,f.Access("free"));var client=new Client{Name="Own Client"};await clients.SaveClient(client);await f.Ats("free").SavePosition(new(){Title="Own Role",Client=client.Name,ClientId=client.Id,AssignedRecruiter="free",Criteria=[new(){Name="Experience",Weight=100}]});await Assert.ThrowsAsync<InvalidOperationException>(()=>f.Ats("free").SavePosition(new(){Title="Extra Role",Client=client.Name,ClientId=client.Id,Criteria=[new(){Name="Experience",Weight=100}]}));}
 [Fact]public async Task FreelancerCanJoinTwoTeamsAndPermissionsRemainSeparate(){await using var f=new Fixture();await f.Init();var own=(await f.Owner("free").Overview()).Workspace;var a=await f.Join("first","free");var b=await f.Join("second","free");Assert.NotEqual(a,b);Assert.Equal(own.Id,await f.Access("free").WorkspaceId());Assert.False(await f.Access("free",a).Can("Clients.Create"));Assert.False(await f.Access("free",b).Can("Clients.Create"));var member=Assert.Single((await f.Team("first").Team()).Members);await f.Team("first").Update(member with{CanCreateClients=true,CanCreatePositions=true});var agency=(await f.Owner("first").Overview()).Workspace;agency.AgencyEnabled=true;await f.Owner("admin").SetAccess(agency);Assert.True(await f.Access("free",a).Can("Clients.Create"));Assert.False(await f.Access("free",b).Can("Clients.Create"));Assert.True(await f.Access("free").Can("Clients.Create"));await using var db=f.Factory.CreateDbContext();Assert.Equal(2,(await WorkspaceContext.Choices(db,(await f.Auth("free").GetAuthenticationStateAsync()).User)).Count(c=>!c.Owner));await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Access("employee",own.Id).Require());}
 [Fact]public async Task MembershipDeactivationLeavesOtherTeamsAndIndependentAccountActive(){await using var f=new Fixture();await f.Init();var a=await f.Join("first","free");var b=await f.Join("second","free");var member=Assert.Single((await f.Team("first").Team()).Members);await f.Team("first").Update(member with{Status="Inactive"});await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Access("free",a).Require());Assert.Equal(b,await f.Access("free",b).WorkspaceId());Assert.True(await f.Access("free").Can("Clients.Create"));await using var db=f.Factory.CreateDbContext();Assert.Equal("Active",(await db.Users.FindAsync("free"))!.Status);Assert.Equal(0,(await f.Owner("first").Usage()).ActiveRecruiters);}
 [Fact]public async Task WorkspaceSelectionDoesNotExposeOtherCompanyPositionsOrAllowOwnerSettings(){await using var f=new Fixture();await f.Init();var a=await f.Join("first","free");var b=await f.Join("second","free");await using(var db=f.Factory.CreateDbContext()){db.Positions.AddRange(new Position{Reference="A",Title="Company A",WorkspaceId=a,AssignedRecruiter="free"},new Position{Reference="B",Title="Company B",WorkspaceId=b,AssignedRecruiter="free"});await db.SaveChangesAsync();}Assert.Equal("Company A",Assert.Single(await f.Ats("free",a).Positions()).Title);Assert.Equal("Company B",Assert.Single(await f.Ats("free",b).Positions()).Title);var otherId=(await f.Ats("free",b).Positions()).Single().Id;await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Access("free",a).RequirePosition(otherId));var auth=f.Auth("free",a);var otherWorkspace=(await f.Owner("first").Overview()).Workspace;await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>new EmployerService(auth,new Access(auth,f.Factory),f.Factory).SaveCompany(otherWorkspace));}
 [Fact]public async Task MasterIdentityDeduplicatesPeopleWhileKeepingPrivateWorkspaceCopies(){await using var f=new Fixture();await f.Init();var a=(await f.Owner("free").Overview()).Workspace.Id;var b=(await f.Owner("first").Overview()).Workspace.Id;await using(var db=f.Factory.CreateDbContext()){var one=new Candidate{Name="Jane Example",Email="jane@example.test",WorkspaceId=a,Notes="Private Freelancer Note"};var two=new Candidate{Name="Jane Example",Email="JANE@example.test",WorkspaceId=b,Notes="Private Employer Note"};db.Candidates.Add(one);await TalentIdentity.Attach(db,one);db.Candidates.Add(two);await TalentIdentity.Attach(db,two);await db.SaveChangesAsync();Assert.Equal(one.PersonId,two.PersonId);Assert.Equal(2,await db.Candidates.CountAsync());Assert.Single(await TalentIdentity.MasterCandidates(db).ToListAsync());}Assert.Single(await f.Ats("free").TalentCandidates());await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Ats("free").TalentCandidates(true));var access=(await f.Owner("free").Overview()).Workspace;access.MasterTalentPoolEnabled=true;await f.Owner("admin").SetAccess(access);var master=Assert.Single(await f.Ats("free").TalentCandidates(true));Assert.Equal("",master.Notes);Assert.False(await f.Access("first").Can("Talent.Master"));}
 [Fact]public async Task SharedContactWithDifferentNamesIsHeldForReviewInsteadOfMerged(){await using var f=new Fixture();await f.Init();await using var db=f.Factory.CreateDbContext();foreach(var name in new[]{"Jane Example","John Example"}){var candidate=new Candidate{Name=name,Email="shared@example.test"};db.Candidates.Add(candidate);await TalentIdentity.Attach(db,candidate);}await db.SaveChangesAsync();Assert.Equal(2,await db.TalentPeople.CountAsync());Assert.All(await db.TalentPeople.ToListAsync(),p=>Assert.True(p.NeedsReview));Assert.Empty(await TalentIdentity.MasterCandidates(db).ToListAsync());}
 [Fact]public async Task AdminCanResolveAnUncertainIdentityWithoutMergingWorkspaceRecords(){await using var f=new Fixture();await f.Init();await using(var db=f.Factory.CreateDbContext()){foreach(var name in new[]{"First Name","Second Name"}){var c=new Candidate{Name=name,Email="shared-contact@example.test"};db.Candidates.Add(c);await TalentIdentity.Attach(db,c);}await db.SaveChangesAsync();}var service=new TalentAdministration(f.Access("admin"),f.Factory);var identities=await service.Review();Assert.Equal(2,identities.Count);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>new TalentAdministration(f.Access("free"),f.Factory).Review());await service.Resolve(identities[0].Id,identities[0].Revision,identities[1].Id);await using var check=f.Factory.CreateDbContext();Assert.Equal(2,await check.Candidates.CountAsync());Assert.Single(await TalentIdentity.MasterCandidates(check).ToListAsync());Assert.Single(await check.Candidates.Select(c=>c.PersonId).Distinct().ToListAsync());}
 [Fact]public async Task NameOnlyCandidatesAreNotAutomaticallyMerged(){await using var f=new Fixture();await f.Init();await using var db=f.Factory.CreateDbContext();var one=new Candidate{Name="Common Name"};var two=new Candidate{Name="Common Name"};Assert.Null(TalentIdentity.ResolveWorkspace([one],two));db.Candidates.Add(one);await TalentIdentity.Attach(db,one);db.Candidates.Add(two);await TalentIdentity.Attach(db,two);await db.SaveChangesAsync();Assert.NotEqual(one.PersonId,two.PersonId);Assert.Empty(await TalentIdentity.MasterCandidates(db).ToListAsync());}
 [Fact]public async Task LegacyUpgradeMovesPositionsAndSeparatesSharedProfilesWithoutChangingAssessmentSnapshots(){
  await using var f=new Fixture();await f.Init();Guid firstPosition,secondPosition,firstAssessment,secondAssessment;var snapshot="Historical Snapshot Must Remain Unchanged";
  await using(var db=f.Factory.CreateDbContext()){var one=await db.Users.FindAsync("free");one!.AccountType=AccountTypes.Legacy;var two=await db.Users.FindAsync("employee");two!.AccountType=AccountTypes.Legacy;var client=new Client{Name="Shared Legacy Client",NormalizedName="SHARED LEGACY CLIENT"};db.Clients.Add(client);var p=new Position{Reference="OLD-1",Client=client.Name,ClientId=client.Id,AssignedRecruiter="free"};var q=new Position{Reference="OLD-2",Client=client.Name,ClientId=client.Id,AssignedRecruiter="employee"};db.Positions.AddRange(p,q);var person=new Candidate{Name="Shared Person",Email="shared-person@example.test",Notes="Admin Private Note"};db.Candidates.Add(person);var a=new Assessment{PositionId=p.Id,CandidateId=person.Id,State="Saved",SnapshotJson=snapshot};var b=new Assessment{PositionId=q.Id,CandidateId=person.Id,State="Saved",SnapshotJson=snapshot};db.Assessments.AddRange(a,b);await db.SaveChangesAsync();firstPosition=p.Id;secondPosition=q.Id;firstAssessment=a.Id;secondAssessment=b.Id;await WorkspaceUpgrade.Apply(db);}
  await using(var db=f.Factory.CreateDbContext()){var a=await db.Positions.FindAsync(firstPosition);var b=await db.Positions.FindAsync(secondPosition);Assert.NotNull(a!.WorkspaceId);Assert.NotNull(b!.WorkspaceId);Assert.NotEqual(a.WorkspaceId,b.WorkspaceId);Assert.NotEqual(a.ClientId,b.ClientId);var one=await db.Assessments.FindAsync(firstAssessment);var two=await db.Assessments.FindAsync(secondAssessment);Assert.NotEqual(one!.CandidateId,two!.CandidateId);Assert.Equal(snapshot,one.SnapshotJson);Assert.Equal(snapshot,two.SnapshotJson);Assert.Equal(2,await db.Candidates.CountAsync());Assert.Single(await TalentIdentity.MasterCandidates(db).ToListAsync());await WorkspaceUpgrade.Apply(db);Assert.Equal(2,await db.Candidates.CountAsync());}
 }
